// The words of an agent's sparkle in a card's Activity tab (docs/specs/026-plan/items.md "The AI sparkle's words"):
// what the run's changes did, never "Generated by AI", which is a comment's alone. Worked out from the change kinds
// each history entry carries. Pure.
import type { ItemHistoryChange, ItemHistoryEntry } from '@liveplanner/items';

type Verb =
  | 'Transitioned'
  | 'Created'
  | 'Edited'
  | 'Renamed'
  | 'Trashed'
  | 'Archived'
  | 'Restored'
  | 'Flagged'
  | 'Unflagged';

function verbOf(change: ItemHistoryChange): Verb {
  switch (change.kind) {
    case 'moved':
      return 'Transitioned';
    case 'created':
      return 'Created';
    case 'trashed':
      return 'Trashed';
    case 'archived':
      return 'Archived';
    case 'untrashed':
    case 'unarchived':
      return 'Restored';
    case 'flagged':
      return 'Flagged';
    case 'unflagged':
      return 'Unflagged';
    case 'set':
      return change.field === 'title' ? 'Renamed' : 'Edited';
    case 'cleared':
    case 'type':
      return 'Edited';
  }
}

// One verb for the whole run reads "{Verb} by AI"; a rename beside other edits is an edit; anything more mixed is
// "Changed by AI".
export function aiRunWords(entries: readonly Pick<ItemHistoryEntry, 'changes'>[]): string {
  const verbs = new Set<Verb>();
  for (const e of entries) for (const c of e.changes) verbs.add(verbOf(c));
  if (verbs.has('Renamed') && verbs.has('Edited')) verbs.delete('Renamed');
  const [only] = verbs;
  return verbs.size === 1 && only ? `${only} by AI` : 'Changed by AI';
}
